document.addEventListener("DOMContentLoaded", function () {
    // Animation d'apparition des éléments au scroll
    const fadeElements = document.querySelectorAll('.fade-in-element');
    function handleVisibility() {
      const triggerPoint = window.innerHeight * 0.8;
      fadeElements.forEach(element => {
        const elementTop = element.getBoundingClientRect().top;
        if (elementTop < triggerPoint) {
          element.classList.add('is-visible');
        } else {
          element.classList.remove('is-visible');
        }
      });
    }
    window.addEventListener('scroll', handleVisibility);
    handleVisibility();
    
    // Gestion de la synchronisation vidéo/audio pour la Playlist
    const playlistVideo = document.getElementById("playlist-video");
    const playlistAudio = document.getElementById("playlist-audio");
    const playlistOverlay = document.getElementById("playlist-overlay");
    if (playlistVideo && playlistAudio && playlistOverlay) {
      // Fonction de synchronisation de l'audio avec la vidéo
      function syncAudio() {
        playlistAudio.currentTime = playlistVideo.currentTime;
      }
      // Lorsque la vidéo démarre, on lance l'audio et on cache l'overlay
      playlistVideo.addEventListener("play", function() {
        syncAudio();
        playlistAudio.play().catch(err => console.error("Erreur lecture audio :", err));
        playlistOverlay.style.opacity = "0";
        playlistOverlay.style.pointerEvents = "none";
      });
      // Lorsque la vidéo est mise en pause, on arrête l'audio et on affiche l'overlay
      playlistVideo.addEventListener("pause", function() {
        playlistAudio.pause();
        playlistOverlay.style.opacity = "1";
        playlistOverlay.style.pointerEvents = "auto";
      });
      // Lors d'un seek, synchroniser l'audio
      playlistVideo.addEventListener("seeking", function() {
        syncAudio();
      });
      // Lors de mises à jour du temps, maintenir la synchronisation si nécessaire
      playlistVideo.addEventListener("timeupdate", function() {
        if (Math.abs(playlistAudio.currentTime - playlistVideo.currentTime) > 0.3) {
          syncAudio();
        }
      });
      // Le clic sur l'overlay déclenche le play/pause
      playlistOverlay.addEventListener("click", function(e) {
        e.stopPropagation();
        if (playlistVideo.paused) {
          playlistVideo.play().catch(err => console.error("Erreur lecture vidéo :", err));
        } else {
          playlistVideo.pause();
        }
      });
      // Le clic direct sur la vidéo (hors des contrôles natifs) déclenche aussi play/pause
      playlistVideo.addEventListener("click", function(e) {
        // Vérifie que l'utilisateur n'a pas cliqué sur un élément des contrôles natifs (ceci est généralement géré par le navigateur)
        if (playlistVideo.paused) {
          playlistVideo.play().catch(err => console.error("Erreur lecture vidéo :", err));
        } else {
          playlistVideo.pause();
        }
      });
    }
    
    // Gestion du bouton musique de fond (background audio)
    const musicToggle = document.getElementById("music-toggle");
    const backgroundAudio = document.getElementById("background-audio");
    let isBackgroundPlaying = false;
    if (musicToggle && backgroundAudio) {
      musicToggle.addEventListener("click", function(e) {
        e.preventDefault();
        e.stopPropagation();
        if (!isBackgroundPlaying) {
          backgroundAudio.play().then(() => {
            isBackgroundPlaying = true;
            // Quand l'audio de fond se lance : fond blanc, icône (note) rouge
            musicToggle.style.background = "#fff";
            musicToggle.style.color = "#E31828";
          }).catch(err => console.error("Erreur lors de la lecture du background audio :", err));
        } else {
          backgroundAudio.pause();
          isBackgroundPlaying = false;
          // Quand l'audio de fond s'arrête : fond dégradé rouge, icône blanche
          musicToggle.style.background = "linear-gradient(45deg, #E31828, #FF5733)";
          musicToggle.style.color = "#fff";
        }
        return false;
      });
    }
  });
  
  document.addEventListener("DOMContentLoaded", function() {
    // Gestion du canvas et signature
    const canvas = document.getElementById('signature-pad');
    const button = document.getElementById('action-button');
    const signaturePad = new SignaturePad(canvas, {
      backgroundColor: 'rgba(255, 255, 255, 1)',
      penColor: 'black'
    });
    
    function resizeCanvas() {
      const ratio = Math.max(window.devicePixelRatio || 1, 1);
      canvas.width = canvas.offsetWidth * ratio;
      canvas.height = canvas.offsetHeight * ratio;
      canvas.getContext('2d').scale(ratio, ratio);
      signaturePad.clear();
    }
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    
    function updateButton() {
      if (signaturePad.isEmpty()) {
        button.textContent = 'SIGN HERE';
        button.disabled = true;
      } else {
        button.textContent = 'SEND PACT';
        button.disabled = false;
      }
    }
    canvas.addEventListener('mouseup', updateButton);
    canvas.addEventListener('touchend', updateButton);
    canvas.addEventListener('mouseout', updateButton);
    
    function openLinks() {
      const url1 = 'https://sunpump.meme/token/TPmPPtsiqHoNPT1XHpudt3L6VAwyuVJ1Sq';
      const url2 = 'https://t.me/grumcoin';
      window.open(url1, '_blank');
      setTimeout(() => {
        window.open(url2, '_blank');
      }, 100);
    }
    
    button.addEventListener('click', function() {
      if (!signaturePad.isEmpty()) {
        openLinks();
      }
    });
    
    canvas.addEventListener('touchstart', function(e) {
      e.preventDefault();
    }, { passive: false });
  });